PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,image TEXT,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,category_id TEXT NOT NULL REFERENCES categories(id),description TEXT NOT NULL,story TEXT NOT NULL DEFAULT '',price REAL NOT NULL,compare_at REAL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',featured INTEGER NOT NULL DEFAULT 0,trending INTEGER NOT NULL DEFAULT 0,best_seller INTEGER NOT NULL DEFAULT 0,is_new INTEGER NOT NULL DEFAULT 0,rating REAL NOT NULL DEFAULT 0,review_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_images(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,url TEXT NOT NULL,alt TEXT NOT NULL DEFAULT '',position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,sku TEXT,color TEXT,size TEXT,stock INTEGER NOT NULL DEFAULT 0,price_delta REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,user_id TEXT,name TEXT NOT NULL,rating INTEGER NOT NULL,title TEXT NOT NULL DEFAULT '',body TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS carts(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,guest_id TEXT,coupon_code TEXT,shipping_method TEXT NOT NULL DEFAULT 'standard',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cart_items(id TEXT PRIMARY KEY,cart_id TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),variant_id TEXT NOT NULL,qty INTEGER NOT NULL,unit_price REAL NOT NULL,created_at TEXT NOT NULL,UNIQUE(cart_id,product_id,variant_id));
CREATE TABLE IF NOT EXISTS wishlists(owner_key TEXT NOT NULL,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,PRIMARY KEY(owner_key,product_id));
CREATE TABLE IF NOT EXISTS recently_viewed(owner_key TEXT NOT NULL,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,viewed_at TEXT NOT NULL,PRIMARY KEY(owner_key,product_id));
CREATE TABLE IF NOT EXISTS coupons(code TEXT PRIMARY KEY,type TEXT NOT NULL,value REAL NOT NULL,min_subtotal REAL NOT NULL DEFAULT 0,max_uses INTEGER NOT NULL DEFAULT 9999,used INTEGER NOT NULL DEFAULT 0,starts_at TEXT,ends_at TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS banners(id TEXT PRIMARY KEY,title TEXT NOT NULL,subtitle TEXT NOT NULL DEFAULT '',cta TEXT NOT NULL DEFAULT '',link TEXT NOT NULL DEFAULT '/shop',image TEXT NOT NULL DEFAULT '',position TEXT NOT NULL DEFAULT 'home',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS subscribers(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,order_no TEXT UNIQUE NOT NULL,user_id TEXT REFERENCES users(id),guest_email TEXT NOT NULL,status TEXT NOT NULL,payment_method TEXT NOT NULL,payment_status TEXT NOT NULL,payment_ref TEXT,subtotal REAL NOT NULL,discount REAL NOT NULL,shipping REAL NOT NULL,tax REAL NOT NULL,total REAL NOT NULL,currency TEXT NOT NULL,coupon_code TEXT,customer_name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',address_line1 TEXT NOT NULL,address_line2 TEXT NOT NULL DEFAULT '',city TEXT NOT NULL,region TEXT NOT NULL DEFAULT '',postal_code TEXT NOT NULL DEFAULT '',country TEXT NOT NULL,tracking_no TEXT,stock_restored INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT,variant_id TEXT,name TEXT NOT NULL,variant_label TEXT NOT NULL DEFAULT '',sku TEXT,qty INTEGER NOT NULL,unit_price REAL NOT NULL,total REAL NOT NULL);
CREATE TABLE IF NOT EXISTS order_events(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,amount REAL NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'completed',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category_id,status);
CREATE INDEX IF NOT EXISTS orders_created_idx ON orders(created_at);
CREATE INDEX IF NOT EXISTS cart_user_idx ON carts(user_id);